//! End-to-end checks of the `miniq` process: framing of stdin and stdout.

use std::io::Write;
use std::process::{Command, Stdio};

fn run(input: &[u8]) -> (String, bool) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("the miniq binary starts");
    child
        .stdin
        .take()
        .expect("stdin is piped")
        .write_all(input)
        .expect("the input fits the pipe buffer");
    let output = child.wait_for_output();
    (
        String::from_utf8(output.stdout).expect("responses are UTF-8"),
        output.status.success(),
    )
}

trait WaitForOutput {
    fn wait_for_output(self) -> std::process::Output;
}

impl WaitForOutput for std::process::Child {
    fn wait_for_output(self) -> std::process::Output {
        self.wait_with_output().expect("miniq exits at end of input")
    }
}

#[test]
fn every_line_gets_one_response_in_order() {
    let (stdout, success) = run(b"{\"Command\": \"Tick\", \"Seconds\": 2}\n\nnot json\n{\"Command\": \"Tick\", \"Seconds\": 3}\n");
    assert!(success);
    assert_eq!(
        stdout,
        concat!(
            "{\"ok\":true,\"Now\":2}\n",
            "{\"ok\":false,\"error\":{\"code\":\"InvalidRequest\",\"message\":\"the line is not valid JSON: EOF while parsing a value at line 1 column 0\"}}\n",
            "{\"ok\":false,\"error\":{\"code\":\"InvalidRequest\",\"message\":\"the line is not valid JSON: expected ident at line 1 column 2\"}}\n",
            "{\"ok\":true,\"Now\":5}\n",
        )
    );
}

#[test]
fn a_final_line_without_newline_counts() {
    let (stdout, success) = run(b"{\"Command\": \"Tick\", \"Seconds\": 4}");
    assert!(success);
    assert_eq!(stdout, "{\"ok\":true,\"Now\":4}\n");
}

#[test]
fn empty_input_produces_no_output() {
    assert_eq!(run(b""), (String::new(), true));
}

#[test]
fn invalid_utf8_is_answered_and_the_next_line_still_runs() {
    let (stdout, success) = run(b"\xff\xfe\n{\"Command\": \"Tick\", \"Seconds\": 1}\n");
    assert!(success);
    let codes: Vec<&str> = stdout.lines().map(|l| if l.contains("InvalidRequest") { "bad" } else { "ok" }).collect();
    assert_eq!(codes, ["bad", "ok"]);
}
EOF
