        ("f.fifo", json!({"Body": "x", "DelaySeconds": 1}), "UnsupportedOperation"),
        ("f.fifo", json!({"Body": "x", "DeduplicationId": "d"}), "MissingParameter"),
        ("f.fifo", json!({"Body": "x", "GroupId": "g"}), "MissingParameter"),
