            "MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hello",
            "ReceiveCount": 1, "SentAt": 5, "FirstReceivedAt": 12
        }]})
    );
    assert_eq!(counts(&mut session, "q"), json!({"Visible": 0, "InFlight": 1, "Delayed": 0}));
}

