mod common;

use common::{Session, code};
use serde_json::{Value, json};

fn handle_command(command: &str, queue: &str, handle: &str) -> Value {
    json!({"Command": command, "QueueName": queue, "ReceiptHandle": handle, "VisibilityTimeout": 10})
