    for handle in ["r-01", "R-1", "r-1 ", "r-2", "r-0", "", "1", "r--1", "r-99999999999999999999999"] {
        for command in ["DeleteMessage", "ChangeMessageVisibility"] {
            let response = session.command(handle_command(command, "q", handle));
            assert_eq!(code(&response), "ReceiptHandleInvalid", "{command} {handle:?}");
